package codex

import (
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"testing"
)

// The contract test pins the hand-written protocol subset to the JSON schema
// generated by `codex app-server generate-json-schema` for SchemaVersion and
// committed under schema/codex/<SchemaVersion>/. It fails when:
//   - a method, notification or server request we use is not in the schema;
//   - a field we send or read does not exist on the schema definition;
//   - an enum value we rely on (turn status, thread status, approval
//     decision) is not in the schema.
// When Codex is upgraded: regenerate the schema into a new directory, bump
// SchemaVersion, and fix whatever this test reports.

func schemaDir(t *testing.T) string {
	t.Helper()
	dir := filepath.Join("..", "..", "schema", "codex", SchemaVersion)
	if _, err := os.Stat(dir); err != nil {
		t.Fatalf("schema for Codex %s not committed at %s: %v", SchemaVersion, dir, err)
	}
	return dir
}

type schemaSet struct {
	defs map[string]map[string]any
}

func loadJSON(t *testing.T, path string) map[string]any {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var m map[string]any
	if err := json.Unmarshal(b, &m); err != nil {
		t.Fatalf("%s: %v", path, err)
	}
	return m
}

func loadSchemas(t *testing.T) *schemaSet {
	dir := schemaDir(t)
	s := &schemaSet{defs: map[string]map[string]any{}}
	bundle := loadJSON(t, filepath.Join(dir, "codex_app_server_protocol.v2.schemas.json"))
	for name, d := range bundle["definitions"].(map[string]any) {
		s.defs[name] = d.(map[string]any)
	}
	// Top-level per-type files (approval requests, v1 initialize, ...).
	for _, sub := range []string{".", "v1"} {
		entries, _ := os.ReadDir(filepath.Join(dir, sub))
		for _, e := range entries {
			if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") || strings.HasPrefix(e.Name(), "codex_app_server") {
				continue
			}
			name := strings.TrimSuffix(e.Name(), ".json")
			m := loadJSON(t, filepath.Join(dir, sub, e.Name()))
			if _, ok := s.defs[name]; !ok {
				s.defs[name] = m
			}
			if inner, ok := m["definitions"].(map[string]any); ok {
				for n, d := range inner {
					if _, ok := s.defs[n]; !ok {
						s.defs[n] = d.(map[string]any)
					}
				}
			}
		}
	}
	return s
}

func methodsOf(t *testing.T, file string) map[string]bool {
	m := loadJSON(t, filepath.Join(schemaDir(t), file))
	out := map[string]bool{}
	for _, v := range m["oneOf"].([]any) {
		props, _ := v.(map[string]any)["properties"].(map[string]any)
		meth, _ := props["method"].(map[string]any)
		if enum, ok := meth["enum"].([]any); ok && len(enum) > 0 {
			out[enum[0].(string)] = true
		}
	}
	return out
}

func jsonFields(t reflect.Type) []string {
	var out []string
	for i := 0; i < t.NumField(); i++ {
		tag := t.Field(i).Tag.Get("json")
		name := strings.Split(tag, ",")[0]
		if name == "" || name == "-" {
			continue
		}
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

func (s *schemaSet) props(t *testing.T, def string) map[string]any {
	t.Helper()
	d, ok := s.defs[def]
	if !ok {
		t.Fatalf("schema has no definition %q", def)
	}
	p, _ := d["properties"].(map[string]any)
	return p
}

func enumStrings(v any) []string {
	var out []string
	var walk func(any)
	walk = func(x any) {
		switch m := x.(type) {
		case map[string]any:
			if e, ok := m["enum"].([]any); ok {
				for _, s := range e {
					if str, ok := s.(string); ok {
						out = append(out, str)
					}
				}
			}
			for _, k := range []string{"oneOf", "anyOf", "allOf"} {
				if arr, ok := m[k].([]any); ok {
					for _, a := range arr {
						walk(a)
					}
				}
			}
			if p, ok := m["properties"].(map[string]any); ok {
				if typ, ok := p["type"]; ok {
					walk(typ)
				}
			}
		}
	}
	walk(v)
	return out
}

func contains(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

func TestContractAgainstSchema(t *testing.T) {
	s := loadSchemas(t)

	requests := methodsOf(t, "ClientRequest.json")
	for _, m := range []string{MethodInitialize, MethodThreadStart, MethodThreadResume, MethodThreadSetName,
		MethodThreadList, MethodThreadRead, MethodThreadUnsubscribe, MethodTurnStart, MethodTurnSteer, MethodTurnInterrupt} {
		if !requests[m] {
			t.Errorf("client request %q not in schema", m)
		}
	}
	if !methodsOf(t, "ClientNotification.json")[NotifyInitialized] {
		t.Errorf("client notification %q not in schema", NotifyInitialized)
	}
	notes := methodsOf(t, "ServerNotification.json")
	for _, m := range []string{NoteThreadStarted, NoteThreadStatusChanged, NoteThreadClosed, NoteTurnStarted,
		NoteTurnCompleted, NoteItemStarted, NoteItemCompleted, NoteAgentMessageDelta, NoteTurnDiffUpdated,
		NoteTokenUsageUpdated, NoteError, NoteRequestResolved} {
		if !notes[m] {
			t.Errorf("server notification %q not in schema", m)
		}
	}
	sreqs := methodsOf(t, "ServerRequest.json")
	for _, m := range []string{RequestCommandApproval, RequestFileChangeApproval} {
		if !sreqs[m] {
			t.Errorf("server request %q not in schema", m)
		}
	}

	// Every field we send or read must exist on its schema definition.
	cases := []struct {
		def string
		v   any
	}{
		{"InitializeParams", InitializeParams{}},
		{"InitializeCapabilities", InitializeCapabilities{}},
		{"ClientInfo", ClientInfo{}},
		{"InitializeResponse", InitializeResponse{}},
		{"Thread", Thread{}},
		{"ThreadStartParams", ThreadStartParams{}},
		{"ThreadStartResponse", ThreadStartResponse{}},
		{"ThreadResumeParams", ThreadResumeParams{}},
		{"ThreadResumeResponse", ThreadResumeResponse{}},
		{"ThreadSetNameParams", ThreadSetNameParams{}},
		{"ThreadListParams", ThreadListParams{}},
		{"ThreadListResponse", ThreadListResponse{}},
		{"ThreadReadParams", ThreadReadParams{}},
		{"ThreadReadResponse", ThreadReadResponse{}},
		{"ThreadUnsubscribeParams", ThreadUnsubscribeParams{}},
		{"ThreadUnsubscribeResponse", ThreadUnsubscribeResponse{}},
		{"TurnStartParams", TurnStartParams{}},
		{"TurnStartResponse", TurnStartResponse{}},
		{"TurnSteerParams", TurnSteerParams{}},
		{"TurnSteerResponse", TurnSteerResponse{}},
		{"TurnInterruptParams", TurnInterruptParams{}},
		{"Turn", Turn{}},
		{"TurnError", TurnError{}},
		{"ThreadStartedNotification", ThreadStartedNotification{}},
		{"ThreadStatusChangedNotification", ThreadStatusChangedNotification{}},
		{"ThreadClosedNotification", ThreadClosedNotification{}},
		{"TurnStartedNotification", TurnNotification{}},
		{"TurnCompletedNotification", TurnNotification{}},
		{"ItemStartedNotification", ItemNotification{}},
		{"ItemCompletedNotification", ItemNotification{}},
		{"AgentMessageDeltaNotification", AgentMessageDeltaNotification{}},
		{"TurnDiffUpdatedNotification", TurnDiffUpdatedNotification{}},
		{"ThreadTokenUsageUpdatedNotification", ThreadTokenUsageUpdatedNotification{}},
		{"ThreadTokenUsage", ThreadTokenUsage{}},
		{"TokenUsageBreakdown", TokenUsageBreakdown{}},
		{"ErrorNotification", ErrorNotification{}},
		{"ServerRequestResolvedNotification", ServerRequestResolvedNotification{}},
		{"CommandExecutionRequestApprovalParams", CommandExecutionRequestApprovalParams{}},
		{"FileChangeRequestApprovalParams", FileChangeRequestApprovalParams{}},
		{"CommandExecutionRequestApprovalResponse", ApprovalResponse{}},
		{"FileChangeRequestApprovalResponse", ApprovalResponse{}},
	}
	for _, c := range cases {
		props := s.props(t, c.def)
		typ := reflect.TypeOf(c.v)
		for _, f := range jsonFields(typ) {
			if _, ok := props[f]; ok {
				continue
			}
			// ItemNotification serves both started and completed shapes.
			if typ == reflect.TypeOf(ItemNotification{}) && (f == "startedAtMs" || f == "completedAtMs") {
				continue
			}
			t.Errorf("%s: field %q not in schema definition %s", typ.Name(), f, c.def)
		}
	}

	// UserInput text and localImage variants, with the fields we send.
	if !contains(enumStrings(s.defs["UserInput"]), "text") {
		t.Error("UserInput has no text variant")
	}
	if !contains(enumStrings(s.defs["UserInput"]), "localImage") {
		t.Error("UserInput has no localImage variant")
	}
	for _, v := range s.defs["UserInput"]["oneOf"].([]any) {
		props, _ := v.(map[string]any)["properties"].(map[string]any)
		typ, _ := props["type"].(map[string]any)
		if e, _ := typ["enum"].([]any); len(e) == 1 && e[0] == "localImage" {
			if _, ok := props["path"]; !ok {
				t.Error("UserInput localImage has no path")
			}
		}
	}
	// Enum values we branch on.
	for _, st := range []string{TurnCompleted, TurnInterrupted, TurnFailed, TurnInProgress} {
		if !contains(enumStrings(s.defs["TurnStatus"]), st) {
			t.Errorf("TurnStatus lacks %q", st)
		}
	}
	for _, st := range []string{"notLoaded", "idle", "systemError", "active"} {
		if !contains(enumStrings(s.defs["ThreadStatus"]), st) {
			t.Errorf("ThreadStatus lacks %q", st)
		}
	}
	if !contains(enumStrings(s.defs["ThreadActiveFlag"]), "waitingOnApproval") {
		t.Error("ThreadActiveFlag lacks waitingOnApproval")
	}
	for _, d := range []string{DecisionAccept, DecisionAcceptForSession, DecisionDecline, DecisionCancel} {
		if !contains(enumStrings(s.defs["CommandExecutionApprovalDecision"]), d) {
			t.Errorf("CommandExecutionApprovalDecision lacks %q", d)
		}
		if !contains(enumStrings(s.defs["FileChangeApprovalDecision"]), d) {
			t.Errorf("FileChangeApprovalDecision lacks %q", d)
		}
	}
	for _, v := range []string{"never", "on-request", "untrusted"} {
		if !contains(enumStrings(s.defs["AskForApproval"]), v) {
			t.Errorf("AskForApproval lacks %q", v)
		}
	}
	for _, v := range []string{"read-only", "workspace-write", "danger-full-access"} {
		if !contains(enumStrings(s.defs["SandboxMode"]), v) {
			t.Errorf("SandboxMode lacks %q", v)
		}
	}
}

// TestInstalledCodexMatchesSchema reports drift between the Codex on PATH and
// the committed schema. Set SWK_STRICT_CODEX_VERSION=1 to make drift fatal.
func TestInstalledCodexMatchesSchema(t *testing.T) {
	path, err := exec.LookPath("codex")
	if err != nil {
		t.Skip("codex not on PATH")
	}
	out, err := exec.Command(path, "--version").Output()
	if err != nil {
		t.Skipf("codex --version: %v", err)
	}
	got := strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(string(out)), "codex-cli"))
	if got != SchemaVersion {
		msg := "installed codex " + got + " differs from committed schema " + SchemaVersion +
			"; regenerate with: codex app-server generate-json-schema --out schema/codex/" + got
		if os.Getenv("SWK_STRICT_CODEX_VERSION") == "1" {
			t.Fatal(msg)
		}
		t.Log(msg)
	}
}
